  Definition UW (ff fp : Z) : list (Z * Z) :=
    [(spz - 16384, spz); (as_FSB H, as_FSB H + AFS_FLAGS); (fp, fp + 1); (ff, ff + 2048); (sh ff, sh ff + 256); (po, po + 20)].

  Lemma out_obj : forall ff fp O N a, fresh_frame H LF 5 ff fp -> O <= a < O + N ->
    AIMG_TOP <= O -> O + N <= AAPP_HI -> (O + N <= ALOWSH_LO \/ AHI_LO <= O) ->
    (O + N <= spz - 16384 \/ spz <= O) ->
    (O + N <= as_FSB H + AFS_FLAGS - 0x1000 \/ as_FSB H + AFS_HDR <= O) ->
    (O + N <= ff \/ ff + 2048 <= O) -> (O + N <= po \/ po + 20 <= O) ->
    outside (UW ff fp) a /\ outside (UW ff fp) (a / 8 + SHBASE) /\ 0 <= a < 2 ^ 47.
Proof.
