    afsb_ok H -> aframe_range H 5 ff fp ->
    (ff + 2048 <= po \/ po + 20 <= ff) -> (ff + 2048 <= pcons \/ pcons + 48 <= ff) ->
    (fp + 1 <= pcons \/ pcons + 48 <= fp) -> (fp + 1 <= po \/ po + 20 <= fp) ->
