  Definition TW (ff fp : Z) : list (Z * Z) :=
    [(spz - 16384, spz); (as_FSB H, as_FSB H + AFS_FLAGS); (fp, fp + 1); (ff, ff + 2048); (sh ff, sh ff + 256);
     (po + 2, po + 4); (po + 8, po + 20)].

  Lemma tw_munch : forall ff fp m1 m', munch (W1 ff fp) m0 m1 -> munch (LbA_SnK.PWF sp po ff fp) m1 m' ->
    munch (TW ff fp) m0 m'.
Proof.
