  Lemma tw_place : forall ff fp, fresh_frame H LF 5 ff fp ->
    as_FSB H + AFS_HDR <= ff /\ ff + 2048 <= as_FSB H + AFS_SIZE /\ ff mod 64 = 0
    /\ as_FSB H + AFS_FLAGS <= fp < as_FSB H + AFS_HDR
    /\ AIMG_TOP <= as_FSB H /\ as_FSB H + AFS_SIZE <= aceil /\ as_FSB H mod 4096 = 0
    /\ (as_FSB H + AFS_SIZE <= ALOWSH_LO \/ AHI_LO <= as_FSB H) /\ aapp (as_FSB H) AFS_SIZE
    /\ sh (as_FSB H) <= sh ff /\ sh ff + 256 <= sh (as_FSB H + AFS_SIZE) /\ 0x800d4c00 <= sh ff
