  Definition TW0 (ff fp : Z) : list (Z * Z) :=
    [(spz - 16384, spz); (as_FSB H, as_FSB H + AFS_FLAGS); (fp, fp + 1); (ff, ff + 2048); (sh ff, sh ff + 256)].

